#!/usr/bin/env bash
# Run this from inside your team-velocity repo folder (where index.html lives).
set -e

echo "Writing new logo assets..."
base64 -d > assets/maharashtra-bearing-logo.png << 'B64EOF'

B64EOF
base64 -d > assets/ansys-synopsys-logo.png << 'B64EOF'

B64EOF

echo "Patching HTML..."
python3 << 'PYEOF'
import io

def patch(path, old, new, label):
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    if old not in content:
        print(f"  [SKIP] {label}: exact block not found in {path} (already changed, or file differs from expected).")
        return
    content = content.replace(old, new, 1)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"  [OK] {label} patched in {path}")

INDEX_OLD = '''<section class="sponsor-strip" aria-label="Current sponsors"><div class="sponsor-strip-label mono">Current sponsors</div><div class="sponsor-window"><div class="sponsor-track"><div class="sponsor-logo"><img src="assets/solidworks-logo.png" alt="SOLIDWORKS"></div><div class="sponsor-logo"><img src="assets/vega-logo.png" alt="VEGA"></div><div class="sponsor-logo"><img src="assets/solidworks-logo.png" alt="SOLIDWORKS"></div><div class="sponsor-logo"><img src="assets/vega-logo.png" alt="VEGA"></div></div></div></section>'''

INDEX_NEW = '''<section class="sponsor-strip" aria-label="Current sponsors"><div class="sponsor-window"><div class="sponsor-track">
  <div class="sponsor-logo"><img src="assets/solidworks-logo.png" alt="SOLIDWORKS"></div>
  <div class="sponsor-logo"><span class="sponsor-wordmark">VEGA</span></div>
  <div class="sponsor-logo"><img src="assets/maharashtra-bearing-logo.png" alt="Maharashtra Bearing & Belting Company"></div>
  <div class="sponsor-logo"><img src="assets/ansys-synopsys-logo.png" alt="Ansys, part of Synopsys"></div>
  <div class="sponsor-logo"><img src="assets/solidworks-logo.png" alt="SOLIDWORKS"></div>
  <div class="sponsor-logo"><span class="sponsor-wordmark">VEGA</span></div>
  <div class="sponsor-logo"><img src="assets/maharashtra-bearing-logo.png" alt="Maharashtra Bearing & Belting Company"></div>
  <div class="sponsor-logo"><img src="assets/ansys-synopsys-logo.png" alt="Ansys, part of Synopsys"></div>
</div></div></section>'''

PARTNER_OLD = '''<section class="sponsor-wall"><div class="shell sponsor-wall-head reveal"><div class="eyebrow mono">Current sponsors</div><h2 class="display">With us now.</h2><p>Our current partners.</p></div><div class="sponsor-window"><div class="sponsor-track"><div class="sponsor-logo"><img src="assets/solidworks-logo.png" alt="SOLIDWORKS"></div><div class="sponsor-logo"><img src="assets/vega-logo.png" alt="VEGA"></div><div class="sponsor-logo"><img src="assets/solidworks-logo.png" alt="SOLIDWORKS"></div><div class="sponsor-logo"><img src="assets/vega-logo.png" alt="VEGA"></div><div class="sponsor-logo"><img src="assets/solidworks-logo.png" alt="SOLIDWORKS"></div><div class="sponsor-logo"><img src="assets/vega-logo.png" alt="VEGA"></div></div></div></section>'''

PARTNER_NEW = '''<section class="sponsor-wall"><div class="shell sponsor-wall-head reveal"><h2 class="display">With us now.</h2><p>Our current partners.</p></div><div class="sponsor-window"><div class="sponsor-track">
  <div class="sponsor-logo"><img src="assets/solidworks-logo.png" alt="SOLIDWORKS"></div>
  <div class="sponsor-logo"><span class="sponsor-wordmark">VEGA</span></div>
  <div class="sponsor-logo"><img src="assets/maharashtra-bearing-logo.png" alt="Maharashtra Bearing & Belting Company"></div>
  <div class="sponsor-logo"><img src="assets/ansys-synopsys-logo.png" alt="Ansys, part of Synopsys"></div>
  <div class="sponsor-logo"><img src="assets/solidworks-logo.png" alt="SOLIDWORKS"></div>
