with open("site.css", "r", encoding="utf-8") as f:
    site_css = f.read()
if "sponsor-wordmark" not in site_css:
    site_css = site_css.rstrip("\n") + "\n\n.sponsor-wordmark{font:900 26px/1 'Big Shoulders Display',Impact,sans-serif;letter-spacing:.02em;text-transform:uppercase;color:var(--ink)}\n@media(max-width:760px){.sponsor-wordmark{font-size:20px}}\n"
    with open("site.css", "w", encoding="utf-8") as f:
        f.write(site_css)
